void enter(int i)=>Navigator.of(context).push(MaterialPageRoute(builder:(_)=>GamePlatformPage(territory:territories[i].name,groups:territories[i].groups)));
@override Widget build(BuildContext c)=>Scaffold(backgroundColor:const Color(0xFF010307),body:LayoutBuilder(builder:(c,b){final compact=b.maxWidth<760;final d=math.min(b.maxWidth*.70,b.maxHeight*.82);return Stack(children:[const Positioned.fill(child:CustomPaint(painter:_GameSpacePainter())),SafeArea(child:Padding(padding:EdgeInsets.all(compact?14:28),child:Row(children:[IconButton(onPressed:()=>Navigator.of(context).pop(),icon:const Icon(Icons.arrow_back_ios_new,size:16)),const SizedBox(width:10),const Text('GAME-WORLD',style:TextStyle(fontSize:16,letterSpacing:4)),const Spacer(),const Text('WORLD',style:TextStyle(fontSize:8,letterSpacing:3,color:Colors.white30))]))),Center(child:SizedBox(width:d,height:d,child:GestureDetector(onTapUp:(e){final h=_hit(e.localPosition,d);if(h!=null)setState(()=>selected=selected==h?null:h);},child:CustomPaint(painter:_GamePlanetPainter(selected:selected),child:Stack(children:[_label('NINTENDO',.30,.28,0,d),_label('SEGA',.70,.30,1,d),_label('PLAYSTATION',.29,.70,2,d),_label('XBOX',.71,.69,3,d),Center(child:Opacity(opacity:selected==null?1:.22,child:const Text('GAME-WORLD',style:TextStyle(fontSize:12,letterSpacing:5,color:Colors.white54))))]))))),if(selected!=null)Positioned(left:compact?14:30,right:compact?14:30,bottom:compact?45:58,child:Center(child:Container(padding:const EdgeInsets.all(16),constraints:const BoxConstraints(maxWidth:620),decoration:BoxDecoration(color:const Color(0xE6090913),borderRadius:BorderRadius.circular(16),border:Border.all(color:Color(0x337F70B0))),child:Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(territories[selected!].name,style:const TextStyle(fontSize:13,letterSpacing:3)),const SizedBox(height:5),Text(territories[selected!].description,style:const TextStyle(fontSize:9,color:Colors.white38))])),TextButton(onPressed:()=>enter(selected!),child:const Text('ENTER'))])))),Positioned(left:compact?16:30,bottom:compact?18:26,child:Text(selected==null?'SELECT A REGION':'SELECTED REGION  •  ENTER TO OPEN',style:const TextStyle(fontSize:8,letterSpacing:2.4,color:Colors.white24))) ]);});
Widget _label(String t,double x,double y,int i,double d){double alpha=.18;if(selected==null||selected==i)alpha=.68;return Positioned(left:d*x-70,top:d*y-25,width:140,child:IgnorePointer(child:Center(child:Text(t,style:TextStyle(fontSize:selected==i?11:9,letterSpacing:2.4,color:Colors.white.withValues(alpha:alpha))))));}
int? _hit(Offset p,double d){final o=Offset(d/2,d/2),r=d*.49;const q=[Offset(-.30,-.25),Offset(.30,-.24),Offset(-.30,.27),Offset(.30,.27)];for(var i=0;i<4;i++){if((p-(o+Offset(q[i].dx*r,q[i].dy*r))).distance<r*.30)return i;}return null;}}
class _GamePlanetPainter extends CustomPainter{final int? selected;const _GamePlanetPainter({required this.selected});@override void paint(Canvas c,Size s){final o=Offset(s.width/2,s.height/2),r=s.shortestSide*.47,rect=Rect.fromCircle(center:o,radius:r);c.drawCircle(o,r*1.10,Paint()..shader=const RadialGradient(colors:[Color(0x335F6E9A),Colors.transparent]).createShader(Rect.fromCircle(center:o,radius:r*1.1)));c.drawCircle(o,r,Paint()..shader=const RadialGradient(center:Alignment(-.38,-.42),radius:1.05,colors:[Color(0xFF667996),Color(0xFF26364B),Color(0xFF080D16)]).createShader(rect));c.save();c.clipPath(Path()..addOval(rect));final q=math.Random(442);const colors=[Color(0xFF806BB5),Color(0xFF5077A8),Color(0xFF756E9C),Color(0xFF4E817D)];const centers=[Offset(-.30,-.25),Offset(.30,-.24),Offset(-.30,.27),Offset(.30,.27)];for(var i=0;i<4;i++){double a=.025;if(selected==null)a=.12;if(selected==i)a=.34;final p=o+Offset(centers[i].dx*r,centers[i].dy*r);for(var n=0;n<7;n++){final j=Offset((q.nextDouble()-.5)*r*.34,(q.nextDouble()-.5)*r*.28);c.drawOval(Rect.fromCenter(center:p+j,width:r*(.22+q.nextDouble()*.24),height:r*(.08+q.nextDouble()*.12)),Paint()..color=colors[i].withValues(alpha:a));}double borderAlpha=.18;if(selected==i)borderAlpha=.62;c.drawCircle(p,r*.19,Paint()..style=PaintingStyle.stroke..strokeWidth=selected==i?2:1..color=colors[i].withValues(alpha:borderAlpha));}c.restore();c.drawCircle(o+Offset(r*.40,r*.08),r*.78,Paint()..shader=RadialGradient(colors:[Colors.transparent,Colors.black.withValues(alpha:.48)]).createShader(Rect.fromCircle(center:o+Offset(r*.40,r*.08),radius:r*.78)));c.drawArc(Rect.fromCircle(center:o,radius:r*1.01),math.pi*.68,math.pi*.72,false,Paint()..style=PaintingStyle.stroke..strokeWidth=1.2..color=Colors.white24);}@override bool shouldRepaint(covariant _GamePlanetPainter old)=>old.selected!=selected;}
class _GameSpacePainter extends CustomPainter{@override void paint(Canvas c,Size s){c.drawRect(Offset.zero&s,Paint()..shader=const RadialGradient(colors:[Color(0xFF15162A),Color(0xFF060710),Color(0xFF010205)]).createShader(Offset.zero&s));final r=math.Random(711);for(var i=0;i<220;i++)c.drawCircle(Offset(r.nextDouble()*s.width,r.nextDouble()*s.height),.2+r.nextDouble()*.7,Paint()..color=Colors.white.withValues(alpha:.04+r.nextDouble()*.10));}@override bool shouldRepaint(covariant _GameSpacePainter old)=>false;}
